// Returns NULL if char not in font.
static inline const font_mb_glyph_t *font_mb_get(char c) {
    unsigned u = (unsigned char)c;
    if (u >= 128 || !font_mb[u].advance) return NULL;
    return &font_mb[u];
}

// Pixel width of a string. MUST agree with how text_mb_draw() advances the pen,
// or the wrap measures lines narrower than they render and text overflows the
// triangle: a character with no glyph (space, and anything outside the set above)
// advances FONT_MB_SPACE_W there, so it has to count for that much here too.
static inline int font_mb_str_width(const char *s) {
    int w = 0;
    for (; *s; s++) {
        const font_mb_glyph_t *g = font_mb_get(*s);
        w += g ? g->advance : FONT_MB_SPACE_W;
    }
    return w;
}
